/** slot 收集工具（自 engine utils 整文件复制，ADR-0008 决策 3——overlay 基座 slot 上行转发消费） */
/**
 * x-slot 插槽标记识别与内容收集（ADR-0056）。
 *
 * 纯函数层：不依赖 engine/scope（`import type` 仅类型层、零运行时依赖），供 collect
 * （出口清单）、component/overlay（内容收集）与 SlotDirective（标记解析）共用。
 *
 * 两侧标记同形：
 * - 裸 `x-slot` / `x-slot.mod` → 默认出口/内容（名 `"default"`）；
 * - `x-slot:名称[.mod]` → 命名出口/内容；
 * - `x-slot-options` 等 `-options` 指令选项属性**不是**标记（不匹配 `x-slot` 正身、
 *   `x-slot.` 修饰前缀、`x-slot:` 属性参数前缀三者任一）。
 *
 * 内容侧值 = 解构形参（`{ item, index }` 简式，非 JSON）；出口侧值 = 对象字面量
 * （组件作用域求值）。形参解析只认简单键（无 rename/默认值）。
 *
 * 传递绑定（ADR-0108）：内容侧另可携带 `x-slot.bind="表达式"`（或别名 `x-slot:名.bind`）
 * ——表达式在调用方作用域求值、展开到出口元素；随 {@link SlotContent.bindingsExpr} 顺流
 * 至 SlotDirective（各收集通道共享本文件，组件/overlay/动态出口天然统一）。
 */


;

/**
 * super 展开产物（ADR-0084）：本段 fallback 的一次独立编译结果。
 * `nodes` 由 SuperDirective 挂入标记元素内；`scopes` 的 parent = 出口 binding
 * （组件作用域基准，出口销毁级联），SuperDirective.destroy 兜底回收（幂等）。
 */
export interface SuperFallback {
    /** 编译产物节点（未挂载，调用方挂入 x-super 标记元素） */
    nodes: ChildNode[];
    /** 本次编译建立的 scopes */
    scopes: AutoSparkScope[];
}

/**
 * super 句柄（ADR-0084）：插槽内容 scope 携带的惰性 fallback 编译入口。
 * 每次调用**独立编译**一份（同段多个 x-super 各自展开、各挂各的 watcher）；
 * 出口无 fallback 子树 → 返回空产物（静默，Q8）。
 */
export type SuperInlet = () => SuperFallback;

/** 插槽标记（出口侧与内容侧共用的识别结果） */
export interface SlotMarker {
    /** 出口/内容名（裸 `x-slot` = `"default"`） */
    name: string;
    /** 标记命中的原始属性名（剥除时用；含修饰符形态） */
    attrName: string;
}

/** 内容侧一段插槽内容的收集产物（已克隆、已剥根标记属性） */
export interface SlotContent {
    /** 段名（`"default"` 或命名） */
    name: string;
    /**
     * 内容节点（深克隆、根标记属性已剥、深层嵌套标记已 warn+剥）。
     * 命名段恒单元素；默认段可为多根（裸子节点按文档序合并）。
     *
     * `mode: "live"` 时语义变更（ADR-0062 shell 机制）：节点是**引擎已编译的活体组件实例**
     * （自带活 scope）——出口直挂不克隆、不再编译、不建内容 scope（销毁权责归构造方，
     * 如 OverlayInstance 对内容/shell 双 scope 的统一回收）。
     */
    nodes: ChildNode[];
    /** 内容侧解构形参键（裸子节点默认段恒 `[]`——无形参） */
    params: string[];
    /** 形参表达式原文（`{ item, index }`；无值 null）——出口侧 watch 注入时按 params 键抽取 */
    paramsExpr: string | null;
    /**
     * 传递绑定表达式（ADR-0108）：`x-slot.bind="…"` / `x-slot:名.bind="…"` 载体属性的值原文。
     * 出口侧经 `callerScope.watch(expr, …, { depth: 2 })` 响应式求值、以 x-bind 展开语义
     * 应用到出口元素（调用方赢）。无载体 null；live 段恒无（引擎编程式构造）。
     */
    bindingsExpr?: string | null;
    /**
     * 段形态（ADR-0062）：`"template"`（缺省）= 模板态克隆（投影时全量编译建 scope）；
     * `"live"` = 活体组件实例（出口直挂，见 nodes 注记）。收集管道（collectSlotSegments）
     * 恒产出 template 态；live 段仅由引擎编程式构造（shell 机制）。
     */
    mode?: "template" | "live";
}

/** `$slots` 注册表条目（ADR-0107 决策六）：最小元数据——v1 从窄，后续按真实需求再扩 */
export interface SlotRegistryEntry {
    /** 段名（键的冗余，遍历解构便利） */
    name: string;
}

/** `$slots` 注册表（ADR-0107）：名 → 条目的只读冻结快照（组件实例域保留键） */
export type SlotRegistry = Record<string, SlotRegistryEntry>;

/**
 * 构建 `$slots` 注册表（ADR-0107 决策六）：内容段 map → 冻结条目快照。
 *
 * 在组件实例化 stash 点同步构建（instantiateComponent / instantiateDetachedComponent）；
 * null/空 map → 冻结空对象（恒注入，`Object.keys($slots)` 遍历友好）。
 */
export function buildSlotsRegistry(map: Map<string, SlotContent> | null | undefined): SlotRegistry {
    const reg: SlotRegistry = {};
    if (map) {
        for (const [name, content] of map) reg[name] = Object.freeze({ name: content.name });
    }
    return Object.freeze(reg);
}

/**
 * 插槽转发声明（ADR-0125）：`x-component-options.slots` 静态清单的一次解析产物，
 * stash 于被消费组件的实例 scope（出口查找链上的持有者）。出口 SlotDirective 查找时
 * 按声明翻译名字（显式映射优先于通配）逐级接力上溯；静态一次解析不响应式。
 */
export interface SlotForwarding {
    /** `*` 通配：未命中显式映射的名字原名上溯（运行时动态集合，覆盖动态出口与闲置段） */
    wildcard: boolean;
    /** 显式映射：本级出口名 → 对外名（裸名直通 = 同名键值；优先于通配） */
    map: Map<string, string>;
}

/**
 * 解析 slots 转发静态清单（ADR-0125 决策三）：逗号清单，项形态 `*`（通配）/
 * 裸名（同名直通）/ `出口名:对外名`（ES 解构 rename 惯例重导出）。
 * 语法非法项（多冒号、空名、项内空白）逐项 warn + 忽略，不拖累整清单。
 */
export function parseForwardSlots(raw: string, warn: (msg: string) => void): SlotForwarding {
    const decl: SlotForwarding = { wildcard: false, map: new Map() };
    for (const item of raw.split(",")) {
        const t = item.trim();
        if (t === "") continue; // 空段（尾逗号等）静默
        if (t === "*") {
            decl.wildcard = true;
            continue;
        }
        const parts = t.split(":");
        if (parts.length > 2) {
            warn(`slots: 非法清单项 "${t}"（至多一个冒号：裸名 或 出口名:对外名），已忽略（ADR-0125）`);
            continue;
        }
        const inner = (parts[0] ?? "").trim();
        const outer = parts.length === 2 ? (parts[1] ?? "").trim() : inner;
        if (inner === "" || outer === "" || /\s/.test(inner) || /\s/.test(outer)) {
            warn(`slots: 非法清单项 "${t}"（须为非空且不含空白的 裸名 或 出口名:对外名），已忽略（ADR-0125）`);
            continue;
        }
        decl.map.set(inner, outer);
    }
    return decl;
}

/** 属性名是否为插槽标记（裸 / 修饰 / 命名三形态；`x-slot-options` 不命中） */
function isSlotAttrName(name: string): boolean {
    return name === "x-slot" || name.startsWith("x-slot.") || name.startsWith("x-slot:");
}

/**
 * 属性名是否为**归属容器**标记（`x-slots` 正身 / `x-slots.修饰` / `x-slots:参数`）。
 *
 * 与 {@link isSlotAttrName} 是两个不同边界：`x-slots` 不以 `x-slot` 整身或 `x-slot.` /
 * `x-slot:` 前缀开头（多一个 `s`），故不会被误判为插槽标记；反之亦然。
 */
export function isSlotsContainerAttrName(name: string): boolean {
    return name === "x-slots" || name.startsWith("x-slots.") || name.startsWith("x-slots:");
}

/** 归属容器标记（`x-slots="覆盖物组件名"`）的识别结果 */
export interface SlotsContainerMarker {
    /** 命中的原始属性名（剥除时用；含修饰符 / 参数形态） */
    attrName: string;
    /** 归属的覆盖物组件名（属性值，静态字符串；空串 = 未提供） */
    name: string;
}

/**
 * 识别元素上的归属容器标记。
 *
 * 归属名走**值**（同 `x-define="名"`），不经属性参数——修饰符 / 参数形态只做识别
 * （防止残留进运行 DOM），不承载语义。
 *
 * @returns 标记（属性名 + 归属名）；无标记返回 null
 */
export function getSlotsContainer(el: HTMLElement): SlotsContainerMarker | null {
    if (!(el instanceof HTMLElement)) return null;
    for (const attr of Array.from(el.attributes)) {
        if (isSlotsContainerAttrName(attr.name)) {
            return { attrName: attr.name, name: attr.value.trim() };
        }
    }
    return null;
}

/**
 * 识别元素上的插槽标记。
 *
 * **普通标记优先、纯绑定载体仅作兜底**（ADR-0108）：绑定属性与标记同元素合写时
 * （`<template x-slot.bind x-slot:header>` 任意书写顺序），名/形参权威属性（plain 形态）
 * 恒为标记位来源——绑定载体不抢标记，顺序无关。
 *
 * @returns 标记（名 + 原始属性名）；无标记返回 null
 */
export function getSlotMarker(el: HTMLElement): SlotMarker | null {
    if (!(el instanceof HTMLElement)) return null;
    let carrierFallback: SlotMarker | null = null;
    for (const attr of Array.from(el.attributes)) {
        const n = attr.name;
        if (isBindCarrierAttrName(n)) {
            // 绑定载体兜底：仅当元素没有任何 plain 标记时才作标记（孤立载体）
            if (!carrierFallback) carrierFallback = markerFromAttrName(n);
            continue;
        }
        const m = markerFromAttrName(n);
        if (m) return m;
    }
    return carrierFallback;
}

/**
 * 单个属性名 → 标记（非插槽属性返回 null）。
 *
 * 名段重组（ADR-0124 点分出口名）：修饰符段除 `bind`（绑定载体语义，ADR-0108）外
 * 以 "." 并回出口名——`x-slot:actions.left` → 出口名 `"actions.left"`；`bind` 段不并入
 * （`x-slot:actions.left.bind` → 槽名 `"actions.left"`）。冒号后首段恒为名首段
 * （`x-slot:bind` = 槽名叫 bind，不是载体）。
 */
function markerFromAttrName(n: string): SlotMarker | null {
    if (n === "x-slot" || n.startsWith("x-slot.")) {
        return { name: "default", attrName: n };
    }
    if (n.startsWith("x-slot:")) {
        const segs = n.slice("x-slot:".length).split(".");
        const head = segs[0] ?? "";
        if (head === "") return { name: "default", attrName: n };
        const rest = segs.slice(1).filter((s) => s !== "bind");
        return { name: [head, ...rest].join("."), attrName: n };
    }
    return null;
}

/** 传递绑定载体属性（ADR-0108）：内容侧 `x-slot.bind` / `x-slot:名.bind` 的识别结果 */
export interface SlotBindingsAttr {
    /** 命中的原始属性名（剥除时用） */
    attrName: string;
    /** 所属槽名（裸形态 = `"default"`；具名别名 = `:` 后段） */
    name: string;
    /** 绑定表达式原文（调用方作用域求值，值语义 = x-bind 属性展开 ADR-0043） */
    value: string;
}

/** 属性名是否为**纯绑定载体**形态（ADR-0108）：`x-slot.bind` / `x-slot.修饰含bind` / `x-slot:名.修饰含bind`。
 *
 * 关键区分：`x-slot:bind` **不是**载体——冒号后第一段恒为槽名（槽恰好叫 bind 时按名处理），
 * bind 只有出现在修饰符位（`.` 后段）才承载绑定语义。
 */
function isBindCarrierAttrName(name: string): boolean {
    if (name === "x-slot.bind") return true;
    if (name.startsWith("x-slot.")) return name.slice("x-slot.".length).split(".").includes("bind");
    if (name.startsWith("x-slot:"))
        return name.slice("x-slot:".length).split(".").slice(1).includes("bind");
    return false;
}

/**
 * 识别元素上的**传递绑定**载体属性（ADR-0108）。
 *
 * 三形态：`x-slot.bind="表达式"`（default 槽）、`x-slot:名.bind="表达式"`（具名别名，
 * 双属性正典下的同元素合写亦命中）、`x-slot.修饰.bind`（修饰符中含 bind 即命中）。
 *
 * 与 {@link getSlotMarker} 正交：标记认名、本函数认绑定载体——同一元素可同时携带
 * 形参标记属性与 `x-slot.bind`（形参与绑定正交共存）。仅内容侧承载语义；
 * 出口侧（x-define 模板内）遇 `.bind` 由 SlotDirective warn + 兼容处理（ADR-0108）。
 *
 * @returns 绑定载体属性（属性名 + 所属槽名 + 表达式原文）；无返回 null
 */
export function getSlotBindingsAttr(el: HTMLElement): SlotBindingsAttr | null {
    if (!(el instanceof HTMLElement)) return null;
    for (const attr of Array.from(el.attributes)) {
        const n = attr.name;
        if (!isBindCarrierAttrName(n)) continue;
        const segs = n.slice("x-slot:".length).split(".");
        // 名段重组（ADR-0124）：修饰符段除 bind 外以 "." 并回槽名（x-slot:actions.left.bind → 槽 "actions.left"）
        const head = segs[0] ?? "";
        const name =
            n.startsWith("x-slot:") && head !== ""
                ? [head, ...segs.slice(1).filter((s) => s !== "bind")].join(".")
                : "default";
        return { attrName: n, name, value: attr.value };
    }
    return null;
}

/**
 * 解析内容侧解构形参 `{ item, index }` → 键列表。
 *
 * 仅认简单键（字母/数字/`_`/`$` 起头的标识符，无 rename、无默认值）。
 *
 * @returns 键列表；空 `{}` / 无值 → `[]`；形态非法（非对象字面量 / 含 rename）→ null（调用方 warn）
 */
export function parseSlotParams(raw: string | null | undefined): string[] | null {
    const s = (raw ?? "").trim();
    if (s === "") return [];
    const m = /^\{([\s\S]*)\}$/.exec(s);
    if (!m) return null;
    const inner = (m[1] ?? "").trim();
    if (inner === "") return [];
    const keys: string[] = [];
    for (const part of inner.split(",")) {
        const k = part.trim();
        if (k === "") continue;
        if (!/^[A-Za-z_$][\w$]*$/.test(k)) return null; // rename / 默认值 / 非法标识符
        keys.push(k);
    }
    return keys;
}

/** 剥除元素自身的全部插槽标记属性（内容克隆根 / 出口重复剥除 / 深层标记放行共用） */
export function stripOwnSlotAttrs(el: HTMLElement): void {
    const toRemove: string[] = [];
    for (const attr of Array.from(el.attributes)) {
        if (isSlotAttrName(attr.name)) toRemove.push(attr.name);
    }
    for (const n of toRemove) el.removeAttribute(n);
}

/**
 * 剥除后代嵌套插槽标记（ADR-0056 决策九：内容侧无深层分段）。
 *
 * 深层 `x-slot:*` → warn + 剥属性（元素保留为普通内容）。
 */
function stripNestedSlotMarkers(root: HTMLElement, warn: (msg: string) => void): void {
    for (const el of Array.from(root.querySelectorAll("*"))) {
        if (!(el instanceof HTMLElement)) continue;
        if (getSlotMarker(el)) {
            warn(
                `x-slot: 插槽内容内部的嵌套 x-slot 标记已忽略（内容分段仅认宿主直接子级，ADR-0056）`,
            );
            stripOwnSlotAttrs(el);
        }
    }
}

/** 文本节点是否纯空白 */
function isWhitespaceText(node: Node): boolean {
    return node.nodeType === Node.TEXT_NODE && (node.nodeValue ?? "").trim() === "";
}

/**
 * 载体元素是否无实质子内容（空白文本 / 注释不算——ADR-0108 绑定载体判定：
 * 空的 `<template x-slot.bind>` 只贡献绑定、不构成默认段内容）。
 */
function isWhitespaceOnlyCarrier(el: HTMLElement): boolean {
    const source = el instanceof HTMLTemplateElement ? el.content : el;
    return Array.from(source.childNodes).every(
        (n) =>
            n.nodeType === Node.COMMENT_NODE ||
            (n.nodeType === Node.TEXT_NODE && (n.nodeValue ?? "").trim() === ""),
    );
}

/**
 * 收集标记元素的内容节点（深克隆、剥根标记、剥深层嵌套标记）。
 *
 * `<template x-slot:…>` 特例：template 不渲染，取其 **content 子节点**展开为多根
 * （对齐 Vue `<template slot>` 直觉）；其余元素保留为包裹层（单根）。
 *
 * @param warn 嵌套标记 warn 透传（collectSlotContent 闭包）
 */
function collectMarkerNodes(child: HTMLElement, warn: (msg: string) => void): ChildNode[] {
    if (child instanceof HTMLTemplateElement) {
        const nodes: ChildNode[] = [];
        for (const n of Array.from(child.content.childNodes)) {
            const clone = n.cloneNode(true);
            if (clone instanceof HTMLElement) stripNestedSlotMarkers(clone, warn);
            nodes.push(clone);
        }
        return nodes;
    }
    const clone = child.cloneNode(true) as HTMLElement;
    stripOwnSlotAttrs(clone);
    stripNestedSlotMarkers(clone, warn);
    return [clone];
}

/**
 * 从宿主**直接子级**收集插槽内容并按名分段（ADR-0056 决策三/七/九）。
 *
 * 分段规则：
 * - 带 `x-slot:名称` 的直接子元素 → 命名段（标记元素保留为包裹层，深克隆）；
 * - 其余（裸文本 / 未标记元素 / 裸 `x-slot` 标记）参与**默认段**；
 * - 默认段归属按文档序「首个胜出」：先见裸子节点则裸段胜（后见裸 `x-slot` 标记 warn 丢弃），
 *   反之标记胜（后见裸子节点 warn 丢弃）；两者只择其一。
 * - 裸子节点 trim 后全纯空白 → 默认段**未提供**（不构成内容）；
 *   命名标记元素**存在即提供**（空/纯空白也覆盖 fallback）。
 * - 同名多段 → 首个胜 + warn。
 * - 逐段比对出口清单 `slots`：无对应出口 → warn + 丢弃（`slots` 缺省视为无出口，全丢）。
 *
 * 模板只读契约（ADR-0002）：一律 `cloneNode(true)`，不摘模板原节点。
 *
 * @param host  宿主（x-component / x-dialog 的 template——ownsChildren 下内容留在模板）
 * @param slots 组件出口清单（`ComponentDef.slots`；undefined = 无出口）
 * @param warn  warn 日志
 * @returns 名 → 内容段；无任何有效段返回 null
 */
export function collectSlotContent(
    host: HTMLElement,
    slots: string[] | undefined,
    warn: (msg: string) => void,
    options?: CollectSlotOptions,
): Map<string, SlotContent> | null {
    return collectSlotSegments(Array.from(host.childNodes), slots, warn, options);
}

/**
 * 按**给定的直接子节点序列**分段并校验出口清单（{@link collectSlotContent} 的主体）。
 *
 * 分段规则与 `collectSlotContent` 完全一致；调用方负责先确定「哪些子节点参与分段」——
 * 覆盖物路径经 {@link collectSlotGroups} 按归属容器分组后逐组调用（ADR-0056 决策十修订）。
 *
 * @param children 参与分段的直接子节点（已在归属容器层面裁剪过）
 * @param slots    组件出口清单（`ComponentDef.slots`；undefined = 无出口）
 * @param warn     warn 日志
 * @returns 名 → 内容段；无任何有效段返回 null
 */
/** 收集选项（ADR-0107）：`skipValidation` = 跳过出口清单校验（组件路径全量收集） */
export interface CollectSlotOptions {
    /**
     * 跳过出口清单校验（ADR-0107 决策五）：动态出口名运行期才可知，命名段全量放行——
     * 未被动态出口消费的段静默闲置不 warn。缺省 false（覆盖物/继承路径维持清单校验）。
     */
    skipValidation?: boolean;
}

export function collectSlotSegments(
    children: ChildNode[],
    slots: string[] | undefined,
    warn: (msg: string) => void,
    options?: CollectSlotOptions,
): Map<string, SlotContent> | null {
    const named = new Map<string, SlotContent>();
    /** 裸默认段节点（文档序） */
    const bareNodes: ChildNode[] = [];
    /** 裸 `x-slot` 标记默认段 */
    let markerDefault: SlotContent | null = null;
    /** 空绑定载体（`<template x-slot.bind>`）的表达式——附着到最终胜出的默认段（ADR-0108） */
    let pendingDefaultBindings: string | null = null;
    /** 首个裸子节点在直接子级中的序号（与标记段比较归属） */
    let firstBareIndex = -1;
    let markerIndex = -1;

    for (let i = 0; i < children.length; i++) {
        const child = children[i]!;
        if (child.nodeType === Node.COMMENT_NODE) continue;
        if (child.nodeType === Node.TEXT_NODE) {
            if (isWhitespaceText(child) && bareNodes.length === 0 && firstBareIndex < 0) {
                // 领先的纯空白不启动裸段（避免前后空白让「全空白」误判为已提供）；
                // 已有裸节点时后续空白并入（保留段内空白文本）。
                // 但若尚无任何默认归属，纯空白仍不计入——全空白最终判未提供。
                // 例外：空白夹在命名段之间时也不该构成默认段——不计入即正确。
                continue;
            }
            if (firstBareIndex < 0) firstBareIndex = i;
            bareNodes.push(child.cloneNode(true));
            continue;
        }
        if (!(child instanceof HTMLElement)) {
            // 其余节点类型（罕见）：计入裸段
            if (firstBareIndex < 0) firstBareIndex = i;
            bareNodes.push(child.cloneNode(true));
            continue;
        }
        const marker = getSlotMarker(child);
        if (!marker) {
            // 未标记元素 → 裸默认段（剥深层嵌套标记，防内容编译期二次实例化 SlotDirective）
            if (firstBareIndex < 0) firstBareIndex = i;
            const clone = child.cloneNode(true) as HTMLElement;
            stripNestedSlotMarkers(clone, warn);
            bareNodes.push(clone);
            continue;
        }
        if (marker.name !== "default") {
            // 命名段
            if (named.has(marker.name)) {
                warn(`x-slot: 插槽内容 "${marker.name}" 重复，后者已忽略（ADR-0056）`);
                continue;
            }
            const bindAttr = getSlotBindingsAttr(child);
            // 别名形态（x-slot:名.bind，ADR-0108）：标记属性本身即绑定载体 → 形参改取
            // 另一条具名属性（可缺省——别名即「无形参」的简写；两者同在时正交共存）
            const paramsAttrName =
                bindAttr && bindAttr.attrName === marker.attrName
                    ? `x-slot:${marker.name}`
                    : marker.attrName;
            const rawVal = child.hasAttribute(paramsAttrName)
                ? child.getAttribute(paramsAttrName)
                : null;
            let params = parseSlotParams(rawVal);
            if (params === null) {
                warn(
                    `x-slot: 内容 "${marker.name}" 的形参须为简单解构形（{ item, index }），已按无形参处理`,
                );
                params = [];
            }
            named.set(marker.name, {
                name: marker.name,
                nodes: collectMarkerNodes(child, warn),
                params,
                paramsExpr: params.length > 0 ? (rawVal ?? "").trim() || null : null,
                bindingsExpr: bindAttr ? bindAttr.value.trim() || null : null,
            });
            continue;
        }
        // 裸 `x-slot` 标记 → 默认段（标记形态）
        const bindAttr = getSlotBindingsAttr(child);
        // 传递绑定载体（ADR-0108 决策六）：标记属性即绑定属性且无 plain `x-slot` 形参属性
        const bindOnly = !!bindAttr && bindAttr.attrName === marker.attrName && !child.hasAttribute("x-slot");
        if (bindOnly) {
            const expr = bindAttr!.value.trim();
            if (expr !== "") {
                if (pendingDefaultBindings === null) pendingDefaultBindings = expr;
                else warn(`x-slot: 默认插槽传递绑定重复，后者已忽略（ADR-0108）`);
            }
            // 空载体（含空白/注释）只贡献绑定、不构成内容段（Q6：绑定与槽标记同生）
            if (isWhitespaceOnlyCarrier(child)) continue;
        }
        if (markerDefault) {
            warn(`x-slot: 默认插槽内容重复（裸 x-slot 标记），后者已忽略（ADR-0056）`);
            continue;
        }
        markerIndex = i;
        const rawVal = bindOnly
            ? child.hasAttribute("x-slot")
                ? child.getAttribute("x-slot")
                : null
            : child.getAttribute(marker.attrName);
        let params = parseSlotParams(rawVal);
        if (params === null) {
            if (rawVal !== null) warn(`x-slot: 默认插槽标记的形参须为简单解构形（{ item }），已按无形参处理`);
            params = [];
        }
        markerDefault = {
            name: "default",
            nodes: collectMarkerNodes(child, warn),
            params,
            paramsExpr: params.length > 0 ? (rawVal ?? "").trim() || null : null,
            bindingsExpr: bindAttr ? bindAttr.value.trim() || null : null,
        };
    }

    // 默认段归属：裸 vs 标记，文档序首个胜 + 另一方 warn 丢弃
    const map = new Map<string, SlotContent>(named);
    const hasBare = bareNodes.length > 0;
    if (hasBare && markerDefault) {
        if (markerIndex >= 0 && firstBareIndex >= 0 && markerIndex < firstBareIndex) {
            warn(
                `x-slot: 默认插槽同时存在裸 x-slot 标记与裸子节点，标记在前——裸子节点已丢弃（ADR-0056）`,
            );
            map.set("default", {
                ...markerDefault,
                bindingsExpr: markerDefault.bindingsExpr ?? pendingDefaultBindings,
            });
        } else {
            warn(
                `x-slot: 默认插槽同时存在裸子节点与裸 x-slot 标记，裸子节点在前——x-slot 标记已丢弃（ADR-0056）`,
            );
            map.set("default", {
                name: "default",
                nodes: bareNodes,
                params: [],
                paramsExpr: null,
                bindingsExpr: pendingDefaultBindings,
            });
        }
    } else if (markerDefault) {
        map.set("default", {
            ...markerDefault,
            bindingsExpr: markerDefault.bindingsExpr ?? pendingDefaultBindings,
        });
    } else if (hasBare) {
        // 裸段全纯空白 → 未提供（leading/trailing 空白已被跳过；中间空白+元素/非空白文本 = 已提供）
        // 再保险：若全部节点仍是纯空白文本 → 未提供
        const allWs = bareNodes.every((n) => isWhitespaceText(n));
        if (!allWs) {
            map.set("default", {
                name: "default",
                nodes: bareNodes,
                params: [],
                paramsExpr: null,
                bindingsExpr: pendingDefaultBindings,
            });
        } else if (pendingDefaultBindings !== null) {
            warn(`x-slot: 默认插槽传递绑定未附着任何内容（仅有绑定载体），已忽略（ADR-0108）`);
        }
    } else if (pendingDefaultBindings !== null) {
        // 空载体 + 无任何默认内容：绑定无段可附着（出口将渲染 fallback，调用方绑定不可达）
        warn(`x-slot: 默认插槽传递绑定未附着任何内容（仅有绑定载体），已忽略（ADR-0108）`);
    }

    // 出口清单校验：无对应出口 → warn + 丢弃（ADR-0107 决策五：组件路径 skipValidation
    // 跳过——动态出口名运行期才可知，未被消费的段静默闲置不 warn）
    if (!options?.skipValidation) {
        const slotSet = slots ? new Set(slots) : null;
        const result = new Map<string, SlotContent>();
        for (const [name, content] of map) {
            if (!slotSet || !slotSet.has(name)) {
                warn(
                    `x-slot: 内容 "${name}" 无对应出口（组件未声明该 x-slot 出口），已丢弃（ADR-0056）`,
                );
                continue;
            }
            result.set(name, content);
        }
        return result.size > 0 ? result : null;
    }
    return map.size > 0 ? map : null;
}

/**
 * 剥除单个后代上的归属容器标记（ADR-0056 决策十修订：归属只认宿主直接子级）。
 *
 * 内层 `x-slots` → warn + 剥属性（元素保留为普通内容，其子节点并入外层组）。
 */
function stripOneContainer(el: HTMLElement, warn: (msg: string) => void): void {
    if (!getSlotsContainer(el)) return;
    warn(`x-slots: 归属容器内部的嵌套 x-slots 已忽略（归属只认宿主直接子级），标记属性已剥除`);
    stripOwnContainerAttrs(el);
}

/** 剥除 root 后代上的全部归属容器标记（root 自身不查——由调用方决定） */
function stripNestedContainers(root: HTMLElement, warn: (msg: string) => void): void {
    for (const el of Array.from(root.querySelectorAll("*"))) {
        if (el instanceof HTMLElement) stripOneContainer(el, warn);
    }
}

/** 剥除元素自身的全部归属容器标记属性 */
function stripOwnContainerAttrs(el: HTMLElement): void {
    const toRemove: string[] = [];
    for (const attr of Array.from(el.attributes)) {
        if (isSlotsContainerAttrName(attr.name)) toRemove.push(attr.name);
    }
    for (const n of toRemove) el.removeAttribute(n);
}

/**
 * 取归属容器的子节点（分段输入）。
 *
 * - `<template x-slots>` 走 `.content`（light childNodes 恒空），其余元素走 `.childNodes`；
 * - 深克隆 + 剥嵌套容器标记——模板只读契约（ADR-0002），不碰原 template；
 * - **容器自身不进内容**（Q11：归属是元信息，不是内容结构，覆盖物内不留多余包裹层）。
 */
function containerChildNodes(el: HTMLElement, warn: (msg: string) => void): ChildNode[] {
    const source = el instanceof HTMLTemplateElement ? el.content : el;
    const nodes: ChildNode[] = [];
    for (const n of Array.from(source.childNodes)) {
        const clone = n.cloneNode(true);
        if (clone instanceof HTMLElement) {
            stripOneContainer(clone, warn); // 容器直接子级再嵌容器
            stripNestedContainers(clone, warn);
        }
        nodes.push(clone);
    }
    return nodes;
}

/**
 * 把覆盖物宿主的直接子节点按**归属**分组（ADR-0056 决策十修订）。
 *
 * 分组规则：
 * - 带 `x-slots="组件名"` 的直接子元素 → 具名组，容器子节点为该组内容（容器自身不进组）；
 *   归属名为空 / 与宿主上的消费者不匹配 / 同名重复 → warn + 丢弃。
 * - 带 `x-slot` 标记但**无容器包裹**的直接子元素 → 隐式组：
 *   宿主只有一个覆盖物消费者时归属它；多个消费者无法判定 → warn + 丢弃。
 * - **裸子节点（文本、未标记元素、注释）不参与**——宿主子节点只属于宿主（按钮标签等，
 *   Q1）；容器**内**的裸子节点才是该组的默认段（写容器即显式归属声明）。
 *
 * @param host      覆盖物宿主（只读 template）
 * @param consumers 宿主上全部覆盖物消费者的组件名（用于隐式归属与校验）
 * @param warn      warn 日志
 * @returns 归属名 → 待分段的子节点；无任何组返回空 Map
 */
export function collectSlotGroups(
    host: HTMLElement,
    consumers: string[],
    warn: (msg: string) => void,
): Map<string, ChildNode[]> {
    const uniq = Array.from(new Set(consumers));
    const groups = new Map<string, ChildNode[]>();
    /** 无容器包裹的标记内容 */
    const implicit: ChildNode[] = [];

    for (const child of Array.from(host.childNodes)) {
        const container = child instanceof HTMLElement ? getSlotsContainer(child) : null;
        if (container) {
            if (container.name === "") {
                warn(`x-slots: 归属容器缺少覆盖物组件名（应写 x-slots="组件名"），容器内容已丢弃`);
                continue;
            }
            if (groups.has(container.name)) {
                warn(`x-slots: 归属容器 "${container.name}" 重复，后者已丢弃`);
                continue;
            }
            if (!uniq.includes(container.name)) {
                warn(
                    `x-slots: 宿主上无名为 "${container.name}" 的覆盖物消费者（现有：${uniq.join("、") || "无"}），容器内容已丢弃`,
                );
                continue;
            }
            groups.set(container.name, containerChildNodes(child as HTMLElement, warn));
            continue;
        }
        // 隐式组只收显式标记；裸子节点是宿主自身内容（Q1），静默跳过
        if (child instanceof HTMLElement && getSlotMarker(child)) implicit.push(child);
    }

    if (implicit.length > 0) {
        if (uniq.length === 1) {
            groups.set(uniq[0]!, implicit);
        } else if (uniq.length > 1) {
            warn(
                `x-slots: 宿主上有 ${uniq.length} 个覆盖物消费者（${uniq.join("、")}），未被归属容器包裹的内容无法判定归属，已丢弃——请用 x-slots="组件名" 分别包裹`,
            );
        } else {
            warn(`x-slots: 宿主上无覆盖物消费者，未被归属容器包裹的内容已丢弃`);
        }
    }
    return groups;
}
