import { deepMerge } from "flex-tools/object/deepMerge";
import type { ComponentDef } from "../component/component-def";

;

;
import {
    OVERLAY_DEFAULTS,
    resolveDataContext,
    type OverlayConfig,
} from "./types";
import { OverlayInstance, type OverlayShellDef } from "./instance";
import { registerInstance, getInstances } from "./registry";
import {
    injectErrorBridge,
    mountComponentHost,
    probeAndMount,
    type OverlayHostCtx,
} from "./contentHost";
import { DIALOG_SHELL_NAME, POPOVER_SHELL_NAME } from "../../../utils/shellNames";

/**
 * 覆盖物定义句柄（ADR-0052 决策 15）：覆盖物的**编程视图**，命令式消费入口。
 *
 * `engine.getOverlay(el, name, options?)` 工厂产出（镜像 `getComponentDeclaration` 查找协议——修订共识 10）。
 * `open()` 返回实例句柄（多实例并存时唯一能精确关闭单个实例的通道）；`close()` 关该覆盖物
 * 当前**全部**打开实例。
 */
export class OverlayHandle {
    readonly engine: AutoSpark<any>;
    /** 覆盖物名（消费 attr 名 / 组件名） */
    readonly name: string;
    /** 组件冻结快照根（实例化模板来源；registry 登记键） */
    readonly snapshot: HTMLElement;
    /** 组件定义（可 null：纯快照组件无 setup） */
    readonly def: ComponentDef | null;
    /** getOverlay 传入的消费者配置级（命令式合并链第二层，等价声明式 x-dialog-options；props 键已剥离） */
    private _options: Record<string, any>;
    /** getOverlay options 的 `props` 键（句柄级默认 props，ADR-0052 v2.3——被 open({props}) 覆盖） */
    private _defaultProps: Record<string, any> | undefined;
    /** 查找锚点 el 所属 scope（`'host'` 基准的挂链目标；getOverlay 无 el 时为 null） */
    private readonly _anchorScope: AutoSparkScope | null;

    constructor(
        engine: AutoSpark<any>,
        name: string,
        snapshot: HTMLElement,
        def: ComponentDef | null,
        options: Record<string, any> | null,
        anchorScope: AutoSparkScope | null = null,
    ) {
        this.engine = engine;
        this.name = name;
        this.snapshot = snapshot;
        this.def = def;
        const { props, ...rest } = options ?? {};
        this._defaultProps = props;
        this._options = rest;
        this._anchorScope = anchorScope;
    }

    /**
     * 打开（ADR-0052 v2.3：props 显式键化——`open({props: {...}, ...配置键})`）：
     *
     * - `props`：显式 props 键，注入组件 data 域（**打开时快照**——JS 对象无表达式载体，
     *   无声明式的持续热更新；覆盖句柄级默认 props）；
     * - `dataContext`（**两栖数据视图基准**，ADR-0053 修订更名自 `scope`）：元素（基准载体）→
     *   `findScopeByEl` 挂链 + 兼作 searchRoot；`'host'`/`'declarer'`（基准名）→ `resolveDataContext`
     *   解析（host 挂 getOverlay 锚点 scope）；缺省 → rootless 全局视图（决策 16 命令式缺省）；
     * - 其余键进配置合并链顶层（`closeOnMask`/`animate`/`at` 等已知配置键；`at` 支持字符串/元素
     *   简写，进链前归一化）。**未知键零防御**（v2.3）：旧隐式 props 写法（`open({userId: 42})`）
     *   与 `visible` 键静默沦入 `OverlayConfig` 自由键，不告警——删干净不设防，排错靠自觉。
     */
    open(opts?: Record<string, any>): OverlayInstance {
        let configLayer: Record<string, any> | undefined;
        let props: Record<string, any> | undefined = this._defaultProps;
        if (opts && typeof opts === "object") {
            const { props: openProps, ...rest } = opts;
            if (openProps !== undefined) props = openProps;
            configLayer = rest;
        }
        const resolved = resolveOverlayConfig(this._options, configLayer);
        // keepalive（ADR-0119）：v1 声明式专属——挂起实例的缓存归属方是消费者指令（回收点在
        // 指令销毁），命令式句柄无缓存可复用，配置不生效（关照常销毁，防挂起实例孤儿化）
        if (resolved.keepalive === true) {
            this.engine.logger.warn(
                `engine.getOverlay("${this.name}"): keepalive 在命令式通道不生效（v1 声明式专属，ADR-0119），已忽略`,
            );
        }
        // 数据视图基准（两栖）：缺省 = rootless（决策 16 命令式缺省）；其余统一经 resolveDataContext 分派
        const { parentScope, scopeEl } =
            resolved.dataContext === undefined
                ? { parentScope: null, scopeEl: null }
                : resolveDataContext(
                      resolved.dataContext,
                      this.def,
                      this._anchorScope,
                      this.engine,
                      (m) => this.engine.logger.warn(`engine.getOverlay("${this.name}"): ${m}`),
                  );
        // mask（ADR-0062 保留语义）：遮罩是引擎结构，本选项控制显隐——缺省 true（模态，
        // 与 x-dialog 同构）；mask:false = 裸面板直挂容器
        const mask = resolved.mask !== false;
        const inst = new OverlayInstance(this.engine, this.name, this.snapshot, this.def, resolved, {
            parentScope,
            searchRoot: scopeEl,
            dataContextEl: scopeEl,
            mask,
            shell: resolveCommandShell(this.engine, this._anchorScope, this.name, resolved, mask),
        });
        registerInstance(this.snapshot, inst);
        inst.open();
        // 内容宿主编排（ADR-0123，共享实现见 contentHost.ts）：错误桥 actions 注入 → 三态
        // 分流生成宿主。props 为打开时快照（open({props}) > 句柄级默认——JS 对象无表达式
        // 载体，无声明式持续热更新），组件路径 JSON 序列化作 x-component 指令值、片段路径
        // 经 initialData 注入数据域。
        // 宿主编译父（决策 2 命令式镜像）：显式 dataContext → 基准 scope；缺省收敛消费处
        // scope（锚点 el 所属 scope——局部 x-define 声明与内容数据上下文严格对齐）。
        const hostParent = resolved.dataContext === undefined ? this._anchorScope : parentScope;
        const ctx = this._hostCtx(hostParent);
        const url = typeof resolved.url === "string" ? resolved.url.trim() : "";
        const propsText = this._serializeProps(props);
        const regenerate = () => {
            const found = ctx.findComponent(this.name);
            if (found) {
                mountComponentHost(ctx, inst, this.name, found.def, propsText, null);
            } else if (url !== "") {
                void probeAndMount(ctx, inst, this.name, url, null, propsText, () => props);
            } else {
                // pending（ADR-0123 决策 1）：面板已开 + x-component pending 占位（注册后自动挂载）
                this.engine.logger.warn(
                    `engine.getOverlay("${this.name}"): 组件当前不可达（锚点 scope 可能已销毁），面板已开并显示加载占位——组件注册后自动挂载（ADR-0123）`,
                );
                mountComponentHost(ctx, inst, this.name, null, propsText, null);
            }
        };
        injectErrorBridge(ctx, inst, regenerate);
        regenerate();
        return inst;
    }

    /**
     * 内容宿主共享上下文（ADR-0123）：命令式通道差异注入——warn 前缀、探测注册位
     * （锚点 scope——x-import 同款语义：注册位在宿主编译父链上可见）、组件查找
     * （getOverlay 同源查找协议：锚点 scope 链 → 全局兜底）、宿主编译父（常量——命令式
     * props 为打开时快照，无声明式「表达式基准随 def 就绪变化」问题）。
     */
    private _hostCtx(hostParent: AutoSparkScope | null): OverlayHostCtx {
        return {
            engine: this.engine,
            warn: (m) => this.engine.logger.warn(`engine.getOverlay("${this.name}"): ${m}`),
            registerScope: hostParent,
            findComponent: (n) => {
                const snapshot =
                    this._anchorScope?.getComponentDeclaration(n) ??
                    this.engine._resolveGlobalComponent(n);
                if (!snapshot) return null;
                return {
                    snapshot,
                    def:
                        this.engine.getComponentDef(snapshot) ??
                        this.engine.getGlobalComponentDef(n) ??
                        null,
                };
            },
            resolveParentScope: () => hostParent,
        };
    }

    /** props 快照 → 对象字面量文本（x-component 指令值；循环引用等序列化失败 warn + 忽略） */
    private _serializeProps(props: Record<string, any> | undefined): string | null {
        if (props === undefined) return null;
        try {
            return JSON.stringify(props);
        } catch (e: any) {
            this.engine.logger.warn(
                `engine.getOverlay("${this.name}"): props 序列化失败，已忽略: ${e?.message ?? e}`,
            );
            return null;
        }
    }

    /** 关闭该覆盖物当前全部打开实例（逐个走「请求关闭」，决策 15） */
    close(): void {
        for (const inst of getInstances(this.snapshot)) {
            inst.requestClose("api");
        }
    }
}

/**
 * 组装覆盖物生效配置（ADR-0052 v2.3 两级链）：深度合并（相邻层 deepMerge：数组替换、
 * undefined 不覆盖、函数整体覆盖）——声明式 `内置默认 < x-dialog-options`（一层）；命令式
 * `内置默认 < getOverlay options < open options`（两层，props 键由调用方在传入前剥离）。
 */
export function resolveOverlayConfig(
    ...layers: Array<Record<string, any> | null | undefined>
): OverlayConfig {
    let merged: Record<string, any> = { ...OVERLAY_DEFAULTS };
    for (const layer of layers) {
        if (layer && typeof layer === "object") {
            // at 简写（字符串/元素）进链前归一化为 { selector }——deepMerge 才能局部覆盖：
            // 换锚只覆盖 selector、保留上层 placement/flip/arrow 等其余锚成员
            let normalized: Record<string, any> = layer;
            const at = layer.at;
            if (at != null && (typeof at === "string" || at instanceof HTMLElement)) {
                normalized = { ...layer, at: { selector: at } };
            }
            merged = deepMerge(merged, normalized, {}) as Record<string, any>;
        }
    }
    return merged as OverlayConfig;
}

/**
 * 命令式 shell 解析（ADR-0062 → ADR-0094 标准链）：`config.shell`（getOverlay options /
 * open options）显式名走锚点 scope 链（就近遮蔽）→ 全局兜底；未配置时按 mask 分派内置
 * shell 裸键——`true` 模态用 `dialog`、`false` 裸面板用 `popover`（同模板，键名表达形态
 * 语义），经标准组件链（`components` > `builtinComponents` 双注册位回退）兜底。
 * 未命中 warn + 回退内置默认。
 */
function resolveCommandShell(
    engine: AutoSpark<any>,
    anchorScope: AutoSparkScope | null,
    overlayName: string,
    config: Record<string, any>,
    mask: boolean,
): OverlayShellDef {
    const raw = config.shell;
    const name = raw == null ? "" : String(raw).trim();
    if (name !== "") {
        const snapshot =
            anchorScope?.getComponentDeclaration(name) ?? engine._resolveGlobalComponent(name);
        if (snapshot) {
            const def =
                engine.getComponentDef(snapshot) ?? engine.getGlobalComponentDef(name) ?? null;
            return { name, snapshot, def };
        }
        engine.logger.warn(
            `engine.getOverlay("${overlayName}"): shell "${name}" 未命中（scope 链与全局组件表均无），回退内置默认 shell（ADR-0062）`,
        );
    }
    // 内置 shell 裸键兜底（ADR-0094：裸键即注册名——用户任一注册位同名覆盖天然生效；
    // 内置种子恒在组件表，断言安全）
    const key = mask ? DIALOG_SHELL_NAME : POPOVER_SHELL_NAME;
    return { name: key, ...engine._resolveGlobalComponentFull(key)! };
}
